test('an automatic autoplay rejection stays moving muted and permits a later manual audition', async () => {
  const { media } = configure();
  media.play.mockRejectedValueOnce(new DOMException('User activation is required', 'NotAllowedError'));
  const view = renderPreview('automatic-browser-fallback', false, 'hover');
  const video = await mountedVideo(view.container);
  await waitFor(() => expect(view.onMuted).toHaveBeenCalledWith(true));
  metadata(video);
  expect(video.muted).toBe(true);
  expect(video.paused).toBe(false);
  expect(video).toHaveAttribute('data-ready');
  expect(media.play).toHaveBeenCalledTimes(2);
  fireEvent(video, new Event('playing'));
  expect(media.play).toHaveBeenCalledTimes(2);
  const sourceWrites = vi.spyOn(HTMLMediaElement.prototype, 'src', 'set');
  view.setIntent('explicit');
  expect(video.muted).toBe(false);
  expect(view.onMuted).toHaveBeenLastCalledWith(false);
  expect(media.play).toHaveBeenCalledTimes(2);
  expect(sourceWrites).not.toHaveBeenCalled();
  expect(view.onStop).not.toHaveBeenCalled();
  view.unmount();
  const next = renderPreview('automatic-browser-fallback', false, 'hover');
  const retried = await mountedVideo(next.container);
  expect(retried.getAttribute('src')).toContain('/stream/automatic-browser-fallback');
  expect(next.onStop).not.toHaveBeenCalled();
});

