test('even a refused muted fallback stops without poisoning the source or retrying indefinitely', async () => {
  const { media } = configure();
  media.play.mockRejectedValueOnce(new DOMException('Audible autoplay denied', 'NotAllowedError'))
    .mockRejectedValueOnce(new DOMException('Muted autoplay denied', 'NotAllowedError'));
  const first = renderPreview('automatic-both-denied', false, 'hover');
  await waitFor(() => expect(first.onStop).toHaveBeenCalledTimes(1));
  expect(media.play).toHaveBeenCalledTimes(2);
  expect(first.container.querySelector('video')).toBeNull();
  first.unmount();
  const next = renderPreview('automatic-both-denied', false, 'hover');
  const video = await mountedVideo(next.container);
  expect(video.getAttribute('src')).toContain('/stream/automatic-both-denied');
  expect(next.onStop).not.toHaveBeenCalled();
});

test('a delayed automatic rejection cannot overwrite a newer manual loading request', async () => {
  const { media } = configure();
  let reject!: (reason: Error) => void;
  media.play.mockImplementationOnce(() => new Promise<void>((_resolve, rejectPlay) => { reject = rejectPlay; }));
  const view = renderPreview('automatic-to-manual-pending', false, 'hover');
  const video = await mountedVideo(view.container);
  view.setIntent('explicit');
  await act(async () => reject(new DOMException('Old automatic request denied', 'NotAllowedError')));
  expect(video.muted).toBe(true);
  expect(view.onMuted).not.toHaveBeenCalled();
  metadata(video);
  expect(video.muted).toBe(false);
  expect(view.onMuted).toHaveBeenLastCalledWith(false);
  expect(view.onStop).not.toHaveBeenCalled();
});

test.each([false, true])('a delayed automatic rejection cannot mute decoded manual sound with hover already decoded=%s', async (hoverDecoded) => {
  const { media } = configure();
  let reject!: (reason: Error) => void;
  media.play.mockImplementationOnce(function (this: HTMLMediaElement) {
    Object.defineProperty(this, 'paused', { configurable: true, value: false });
    return new Promise<void>((_resolve, rejectPlay) => { reject = rejectPlay; });
  });
  const view = renderPreview(`automatic-late-after-manual-${hoverDecoded}`, false, 'hover');
  const video = await mountedVideo(view.container);
  if (hoverDecoded) metadata(video);
  view.setIntent('explicit');
  if (!hoverDecoded) metadata(video);
  expect(video.muted).toBe(false);
  expect(video).toHaveAttribute('data-ready');
  video.currentTime = 6.5;
  const sourceWrites = vi.spyOn(HTMLMediaElement.prototype, 'src', 'set');
  const calls = { play: media.play.mock.calls.length, pause: media.pause.mock.calls.length,
    load: media.load.mock.calls.length, muted: view.onMuted.mock.calls.length };
  await act(async () => reject(new DOMException('Superseded automatic playback denied', 'NotAllowedError')));
  expect(video.muted).toBe(false);
  expect(video.paused).toBe(false);
  expect(video.currentTime).toBe(6.5);
  expect(video).toHaveAttribute('data-ready');
  expect(view.onMuted).toHaveBeenLastCalledWith(false);
  expect(view.onMuted).toHaveBeenCalledTimes(calls.muted);
  expect(media.play).toHaveBeenCalledTimes(calls.play);
  expect(media.pause).toHaveBeenCalledTimes(calls.pause);
  expect(media.load).toHaveBeenCalledTimes(calls.load);
  expect(sourceWrites).not.toHaveBeenCalled();
  expect(view.onStop).not.toHaveBeenCalled();
});

test('a late outgoing clip policy rejection cannot stop a decoded original audition', async () => {
  const { media } = configure();
  let reject!: (reason: Error) => void;
  media.play.mockImplementationOnce(function (this: HTMLMediaElement) {
    Object.defineProperty(this, 'paused', { configurable: true, value: false });
    return new Promise<void>((_resolve, rejectPlay) => { reject = rejectPlay; });
  });
  const view = renderPreview('outgoing-policy-rejection', true, 'hover');
  const clip = await mountedVideo(view.container);
  metadata(clip, 6);
  view.setIntent('explicit');
  const original = view.container.querySelector('video[src*="/stream/"]') as HTMLVideoElement;
  metadata(original);
  expect(original.muted).toBe(false);
  const mutedCalls = view.onMuted.mock.calls.length;
  await act(async () => reject(new DOMException('Old clip request denied', 'NotAllowedError')));
  expect(original.muted).toBe(false);
  expect(original.paused).toBe(false);
  expect(original).toHaveAttribute('data-ready');
  expect(clip.paused).toBe(true);
  expect(view.onMuted).toHaveBeenCalledTimes(mutedCalls);
  expect(view.onStop).not.toHaveBeenCalled();
});

