test.each(['intent', 'sourcechange', 'play', 'playing'])('formal %s silences and pauses the preview before notifying its card', async (type) => {
  configure();
  let publish!: (event: PlayerPlaybackEvent) => void;
  const actualSubscribe = playerStore.subscribePlaybackEvents;
  vi.spyOn(playerStore, 'subscribePlaybackEvents').mockImplementation((listener) => {
    publish = listener;
    return actualSubscribe(listener);
  });
  const view = renderPreview(`formal-${type}`);
  const video = await mountedVideo(view.container);
  metadata(video);
  expect(video.muted).toBe(false);
  expect(video.paused).toBe(false);
  const stoppedStates: Array<{ muted: boolean; paused: boolean }> = [];
  view.onStop.mockImplementation(() => stoppedStates.push({ muted: video.muted, paused: video.paused }));
  act(() => {
    if (type === 'intent') playerStore.notePlaybackIntent();
    else publish({ type, media: null, item: mainItem, sourceGeneration: 1, room: null });
  });
  expect(stoppedStates).toEqual([{ muted: true, paused: true }]);
  expect(view.container.querySelector('video')).toBeNull();
  expect(video).not.toHaveAttribute('src');
});

test('a newer audible preview silences the previous owner before its card is notified', async () => {
  configure();
  const first = renderPreview('audible-owner-first');
  const firstVideo = await mountedVideo(first.container);
  metadata(firstVideo);
  const stoppedStates: Array<{ muted: boolean; paused: boolean }> = [];
  first.onStop.mockImplementation(() => stoppedStates.push({ muted: firstVideo.muted, paused: firstVideo.paused }));
  const second = renderPreview('audible-owner-second');
  const secondVideo = await mountedVideo(second.container);
  metadata(secondVideo);
  expect(stoppedStates).toEqual([{ muted: true, paused: true }]);
  expect(first.container.querySelector('video')).toBeNull();
  expect(secondVideo.muted).toBe(false);
  expect(document.querySelectorAll('video[data-video-preview]')).toHaveLength(1);
});

