test('a new card owner releases both staged layers before its own audio starts', async () => {
  configure();
  const first = renderPreview('staged-owner-first', true, 'hover');
  const clip = await mountedVideo(first.container);
  metadata(clip, 6);
  first.setIntent('explicit');
  const original = first.container.querySelector('video[src*="/stream/"]') as HTMLVideoElement;
  const frames = frameDelivery(original);
  metadata(original);
  const states: boolean[] = [];
  first.onStop.mockImplementation(() => states.push([clip, original].every(video => video.muted && video.paused)));
  const second = renderPreview('staged-owner-second');
  const newOwner = await mountedVideo(second.container);
  metadata(newOwner);
  expect(states).toEqual([true]);
  expect(newOwner.muted).toBe(false);
  expect(first.container.querySelector('video')).toBeNull();
  frames.present();
  expect(original.muted).toBe(true);
  expect(first.onReady).toHaveBeenCalledTimes(1);
  expect(document.querySelectorAll('video[data-video-preview]')).toHaveLength(1);
});

test.each(['pending', 'outgoing', 'retiring'])('reverting to a decoded source during %s replacement reuses its live decoder', async (phase) => {
  const { media } = configure();
  const id = `source-reversal-${phase}`;
  const view = renderPreview(id);
  const first = await mountedVideo(view.container);
  metadata(first);
  first.currentTime = 6.5;
  vi.useFakeTimers();
  view.setId(`${id}-replacement`);
  const replacement = view.container.querySelector(`video[src$="${id}-replacement"]`) as HTMLVideoElement;
  if (phase !== 'pending') metadata(replacement);
  const sourceWrites = vi.spyOn(HTMLMediaElement.prototype, 'src', 'set');
  const playCalls = media.play.mock.calls.length;
  act(() => {
    if (phase === 'retiring') vi.advanceTimersByTime(80);
    view.setId(id);
  });
  expect(view.container.querySelector(`video[src$="${id}"]`)).toBe(first);
  expect(first.style.opacity).toBe('1');
  expect(first.muted).toBe(false);
  expect(first.paused).toBe(false);
  expect(first.currentTime).toBe(6.5);
  expect(sourceWrites).not.toHaveBeenCalled();
  expect(media.play).toHaveBeenCalledTimes(playCalls);
  expect(view.onStop).not.toHaveBeenCalled();
  act(() => vi.advanceTimersByTime(80));
  expect(view.container.querySelectorAll('video')).toHaveLength(1);
  expect(first).toHaveAttribute('src');
});

test('rapid mute and unmute restore the original gain target and cancellation never enables late sound', async () => {
  configure();
  const view = renderPreview('stable-gain', true);
  const video = await mountedVideo(view.container);
  metadata(video);
  vi.useFakeTimers();
  view.setMuted(false);
  expect(video.volume).toBe(0);
  act(() => vi.advanceTimersByTime(32));
  expect(video.volume).toBeGreaterThan(0);
  expect(video.volume).toBeLessThan(1);
  view.setMuted(true);
  expect(video.muted).toBe(true);
  expect(video.volume).toBe(1);
  view.setMuted(false);
  act(() => vi.advanceTimersByTime(80));
  expect(video.volume).toBe(1);
  expect(video.muted).toBe(false);
  view.setMuted(true);
  act(() => vi.advanceTimersByTime(200));
  expect(video.muted).toBe(true);
  expect(video.volume).toBe(1);
});
